codeExamples.code:
# aws_db_instance.main must be replaced
-/+ resource "aws_db_instance" "main" {
      ~ identifier = "db-prod" -> "db-production" # forces replacement

terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.40" }
  }
}

provider "aws" { region = "ap-southeast-1" }

data "aws_vpc" "shared" {
  tags = { Name = "platform-vpc" }   # do team infra quản lý
}

resource "aws_security_group" "api" {
  vpc_id = data.aws_vpc.shared.id    # chỉ tham chiếu
}

provider "registry.terraform.io/hashicorp/aws" {
  version     = "5.42.0"
  constraints = "~> 5.40"
  hashes      = ["h1:..."]
}

resource "aws_subnet" "app" {
  vpc_id = aws_vpc.main.id      # implicit dependency, đủ rồi
}

resource "aws_instance" "app" {
  depends_on = [aws_iam_role_policy.s3_access]  # app đọc S3 lúc boot
}

terraform {
  backend "s3" {
    bucket         = "acme-tfstate"
    key            = "prod/network/terraform.tfstate"
    region         = "ap-southeast-1"
    encrypt        = true
    dynamodb_table = "tf-locks"   # locking
  }
}

module "vpc" {
  source  = "git::ssh://git@github.com/acme/tf-modules.git//vpc?ref=v2.3.0"
  cidr    = "10.0.0.0/16"
  azs     = ["ap-southeast-1a", "ap-southeast-1b"]
}

# count: xoá "staging" khỏi list -> aws_s3_bucket.b[1] doi tu staging sang prod
resource "aws_s3_bucket" "b" {
  count  = length(var.envs)          # ["dev", "staging", "prod"]
  bucket = "acme-${var.envs[count.index]}"
}

# for_each: dia chi la aws_s3_bucket.b["prod"], on dinh
resource "aws_s3_bucket" "b" {
  for_each = toset(var.envs)
  bucket   = "acme-${each.key}"
}

import {
  to = aws_instance.legacy_api
  id = "i-0abc123def456"
}

resource "aws_instance" "legacy_api" {
  # terraform plan -generate-config-out=generated.tf sinh khung san
}

moved {
  from = aws_instance.api
  to   = module.api_service.aws_instance.this
}

variable "db_password" { type = string, sensitive = true }
output "endpoint" { value = aws_db_instance.main.address }
# terraform output -json van in ra duoc gia tri that

resource "aws_db_instance" "main" {
  deletion_protection       = true      # chan o tang AWS
  skip_final_snapshot       = false     # giu snapshot cuoi
  backup_retention_period   = 30

  lifecycle {
    prevent_destroy = true              # plan co destroy la fail luon
  }
}

# tranh
provisioner "remote-exec" {
  inline = ["apt-get install -y nginx"]
}

provider "aws" { region = "ap-southeast-1" }

provider "aws" {
  alias  = "us_east"
  region = "us-east-1"
}

resource "aws_acm_certificate" "cdn" {
  provider = aws.us_east      # CloudFront bat buoc cert o us-east-1
  domain_name = "acme.vn"
}

module "dr" {
  source    = "./modules/service"
  providers = { aws = aws.us_east }
}

resource "aws_launch_template" "app" {
  name_prefix = "app-"        # bat buoc: ten phai unique

  lifecycle {
    create_before_destroy = true
  }
}

data "terraform_remote_state" "network" {
  backend = "s3"
  config  = { bucket = "acme-tfstate", key = "prod/network/terraform.tfstate" }
}

resource "aws_instance" "api" {
  subnet_id = data.terraform_remote_state.network.outputs.private_subnet_ids[0]
}

provider "aws" {
  default_tags {
    tags = {
      Environment = var.env
      Owner       = "team-payment"
      Service     = "checkout-api"
      ManagedBy   = "terraform"    # phan biet voi resource tao tay
    }
  }
}

provider "aws" { max_retries = 10 }

resource "aws_db_instance" "main" {
  timeouts { create = "60m" }   # RDS tao lau hon default
}

module "rds" {
  source  = "app.terraform.io/acme/rds/aws"
  version = "~> 3.2"        # registry
}

module "vpc" {
  source = "git::ssh://git@github.com/acme/tf-modules.git//vpc?ref=v2.3.0"
}

locals { prefix = "pr-${var.pr_number}" }

resource "aws_s3_bucket" "assets" {
  bucket = "${local.prefix}-acme-assets"   # ten global unique
}
